import{_ as t,o as a,c as _,ac as o}from"./chunks/framework.B-3EzaJq.js";const b=JSON.parse('{"title":"中国共产党第十二次全国代表大会主席团致王德同志的信","description":"","frontmatter":{"prev":{"text":"中国共产党第十二次全国代表大会选举办法","link":"./中国共产党第十二次全国代表大会选举办法"},"next":{"text":"中国共产党第十二次全国代表大会主席团致许在廉同志的信","link":"./中国共产党第十二次全国代表大会主席团致许在廉同志的信"}},"headers":[],"relativePath":"12/中国共产党第十二次全国代表大会主席团致王德同志的信.md","filePath":"12/中国共产党第十二次全国代表大会主席团致王德同志的信.md"}'),r={name:"12/中国共产党第十二次全国代表大会主席团致王德同志的信.md"};function s(c,e,i,l,n,p){return a(),_("div",null,[...e[0]||(e[0]=[o('<h1 id="中国共产党第十二次全国代表大会主席团致王德同志的信" tabindex="-1">中国共产党第十二次全国代表大会主席团致王德同志的信 <a class="header-anchor" href="#中国共产党第十二次全国代表大会主席团致王德同志的信" aria-label="Permalink to &quot;中国共产党第十二次全国代表大会主席团致王德同志的信&quot;">​</a></h1><p><em>（一九八二年九月九日）</em></p><p>王德同志：</p><p>  大会主席团收到了您给胡耀邦同志的信。您在信中恳切地提出不做中央顾问委员会委员候选人。主席团常委进行了认真研究，考虑到您的健康状况和您的诚挚愿望，经主席团全体会议讨论通过，同意您的意见。我们谨代表党的十二大全体代表，对您在长期革命和建设工作中对党和国家所作的重要贡献，表示衷心的敬意！希望您继续关心党和人民的事业，并祝您健康长寿！</p><div class="sig-block-b"><div class="text-center"><p><strong>中国共产党第十二次<br>全国代表大会主席团</strong><br>一九八二年九月九日</p></div></div><hr><h1 id="王德同志的信" tabindex="-1">王德同志的信 <a class="header-anchor" href="#王德同志的信" aria-label="Permalink to &quot;王德同志的信&quot;">​</a></h1><blockquote><p>耀邦同志：</p><p>  仲夷同志回来说，中央拟提名我为中央顾问委员会委员的候选人。我深感不妥。我年纪大了，现在已过七十六周岁，兼之身体不好有病，难于胜任。广东老同志较多，厅局干部要退下来的会较多，为着工作较利于顺利进行，省委也应有人带头离休才好。否则，免不了有人会说省委要我们退下来，你们老同志这么多为什么没有人退下来。在省委的同志中我退下来最为适当。因之我坚决要求离休。这样做于公于私均为有利。恳求允许，谨致</p><p>敬礼</p></blockquote><blockquote class="blockquote-offset"><div class="sig-block-b"><div class="text-center"><p>王德<br>八月十七日</p></div></div></blockquote>',9)])])}const u=t(r,[["render",s]]);export{b as __pageData,u as default};
